<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_permission('salary.view_own');$pdo=staff_db();$staff=current_staff();$s=$pdo->prepare("SELECT * FROM salary_records WHERE staff_id=? ORDER BY salary_year DESC,salary_month DESC");$s->execute([$staff['id']]);$rows=$s->fetchAll();$pageTitle='My Salary';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Private</p><h1>My salary</h1></div></div><?php foreach($rows as $r):?><section class="staff-panel salary-card"><div class="rowtop"><div><h2><?= h(date('F',mktime(0,0,0,(int)$r['salary_month'],1))) ?> <?= h($r['salary_year']) ?></h2><span class="pill"><?= h($r['payment_status']) ?></span></div><strong class="salary-net"><?= money($r['net_salary']) ?></strong></div><div class="salary-grid"><span>Basic<b><?= money($r['basic_salary']) ?></b></span><span>Overtime<b><?= money($r['overtime_amount']) ?></b></span><span>Allowance<b><?= money($r['allowance_amount']) ?></b></span><span>Commission<b><?= money($r['commission_amount']) ?></b></span><span>Bonus<b><?= money($r['bonus_amount']) ?></b></span><span>Deductions<b>-<?= money($r['deduction_amount']+$r['advance_deduction']) ?></b></span></div></section><?php endforeach;?></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
